Object.assign(definitions, EXAMPLE_MASKS);

for (const definition of Object.values(definitions)) {
  definition.regions.forEach(Object.freeze);
  Object.freeze(definition.regions);
  Object.freeze(definition);
}
export const NUMERIC_MASKS = Object.freeze(definitions);

/** Coordinates apply only to the exact, untouched local sample image. */
export function getNumericMaskDefinition(questionOrId) {
  if (typeof questionOrId === 'string') return NUMERIC_MASKS[questionOrId] || null;
  const q = questionOrId || {};
  const match = /^assets\/questions\/(q\d+|sample-school-\d+-\d+)\.(png|svg)$/.exec(String(q.image || ''));
  if (match && ((match[1].startsWith('sample-') ? 'svg' : 'png') !== match[2])) return null;
  if (!match || (NUMERIC_MASKS[q.id] && q.id !== match[1])) return null;
  return NUMERIC_MASKS[match[1]] || null;
}

const escapeAttribute = value => String(value ?? '').replace(/[&<>"']/g, c => ({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
let instanceId = 0;

/** Use the same viewBox for the image and masks so responsive sizing cannot offset them. */
export function renderNumericQuestionImage(q, {locked = false, alt = '', maxHeight} = {}) {
  const definition = getNumericMaskDefinition(q);
  if (!definition) return '<span class="numeric-image-unavailable">문항 미리보기를 준비하고 있습니다.</span>';
  const {width, height, regions} = definition;
  const id = `numeric-mask-${++instanceId}`;
  const size = Number(maxHeight);
  const style = Number.isFinite(size) && size > 0 ? ` style="--numeric-question-max-height:${Math.min(size, 2000)}px"` : '';
  const source = `<image href="${escapeAttribute(q.image)}" width="${width}" height="${height}"/>`;
  const masked = locked ? `<defs><filter id="${id}-blur" x="-10%" y="-10%" width="120%" height="120%" color-interpolation-filters="sRGB"><feGaussianBlur stdDeviation="3.2"/></filter><clipPath id="${id}-clip" clipPathUnits="userSpaceOnUse">${regions.map(([x,y,w,h]) => `<rect x="${(x*width).toFixed(3)}" y="${(y*height).toFixed(3)}" width="${(w*width).toFixed(3)}" height="${(h*height).toFixed(3)}"/>`).join('')}</clipPath></defs><g clip-path="url(#${id}-clip)"><rect width="${width}" height="${height}" fill="white"/><image href="${escapeAttribute(q.image)}" width="${width}" height="${height}" filter="url(#${id}-blur)"/></g>` : '';
  return `<svg class="numeric-question-image" xmlns="http://www.w3.org/2000/svg" viewBox="0 0 ${width} ${height}" width="${width}" height="${height}" preserveAspectRatio="xMidYMin meet" role="img" aria-label="${escapeAttribute(alt || `${q.grade || ''} ${q.number || ''}번 ${q.title || ''} 문제`)}" data-numeric-mask-count="${locked ? regions.length : 0}"${style}>${source}${masked}</svg>`;
}
